{
  "story": "How much does this split improve purity? Compute each node's Gini: G = 1 − Σp², where p is its class proportion. Start with the parent, then inspect both children. Weight child impurities by sample fractions before subtracting from the parent. The final comparison shows Gini gain; entropy-based information gain uses entropy instead.",
  "aha": {
    "stateId": "gain",
    "observation": "Weighting both children gives remaining impurity 0.250; subtracting it from the parent's 0.500 gives a Gini gain of 0.250."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "calculation-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell, with the story above the experiment. Keep step position and calculation progress on this rail.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "split-picture",
      "kind": "fixed-picture",
      "presentation": "Keep Parent, Left child, and Right child visible in fixed positions. Highlight only the active region. Letters represent equally weighted samples.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "calculation-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the active region without covering samples. Use the bound text as the status line; show its reason beneath.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "impurity-readouts",
      "kind": "value-readout",
      "presentation": "Report numbers only here, beneath the picture. Gini is dimensionless, ranging from zero to one-half for these binary classes. Round results to three decimals.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "calculation-step",
      "kind": "index",
      "items": "variant.states",
      "label": "Calculation step",
      "presentation": "Use Previous and Next with visible focus and keyboard operation. Default to parent; advance one state within parent through gain. Preserve disabled boundary names. Every state persists until another action. Brief parameter-control budget: zero, excluding navigation and reset."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the parent state and all defaults. Support keyboard activation and visible focus. Reference captures must show gain before reset."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Fixed binary split with unequal child sizes",
        "regions": [
          {
            "id": "parent",
            "label": "Parent",
            "values": ["A", "A", "A", "B", "B", "B"]
          },
          {
            "id": "left",
            "label": "Left child",
            "values": ["A", "A"]
          },
          {
            "id": "right",
            "label": "Right child",
            "values": ["A", "B", "B", "B"]
          }
        ],
        "links": [
          {
            "from": "parent",
            "to": "left",
            "label": "Left subset"
          },
          {
            "from": "parent",
            "to": "right",
            "label": "Right subset"
          }
        ],
        "states": [
          {
            "id": "parent",
            "label": "Parent impurity",
            "short": "Parent",
            "sentence": "Calculate the Parent's impurity before evaluating the split.",
            "why": "Class proportions use this node's samples as the denominator.",
            "active": ["parent"],
            "calloutRegion": "parent",
            "readouts": [
              {
                "id": "parent-gini",
                "label": "Parent Gini",
                "value": "1 − (3/6)² − (3/6)² = 0.500"
              }
            ]
          },
          {
            "id": "left",
            "label": "Left child impurity",
            "short": "Left",
            "sentence": "Calculate the Left child's impurity using only its own samples.",
            "why": "Every sample belongs to the same class, so this child is pure.",
            "active": ["left"],
            "calloutRegion": "left",
            "readouts": [
              {
                "id": "left-gini",
                "label": "Left child Gini",
                "value": "1 − (2/2)² − (0/2)² = 0.000"
              }
            ]
          },
          {
            "id": "right",
            "label": "Right child impurity",
            "short": "Right",
            "sentence": "Calculate the Right child's impurity using its own class proportions.",
            "why": "This child contains both classes, so its impurity remains positive.",
            "active": ["right"],
            "calloutRegion": "right",
            "readouts": [
              {
                "id": "right-gini",
                "label": "Right child Gini",
                "value": "1 − (1/4)² − (3/4)² = 0.375"
              }
            ]
          },
          {
            "id": "gain",
            "label": "Weighted impurity and gain",
            "short": "Gain",
            "sentence": "Subtract the sample-weighted child impurity from the Parent's impurity.",
            "why": "The larger Right child contributes more; an unweighted average would misrepresent the split.",
            "active": ["parent"],
            "calloutRegion": "parent",
            "readouts": [
              {
                "id": "parent-gini",
                "label": "Parent Gini",
                "value": "0.500"
              },
              {
                "id": "weighted-gini",
                "label": "Weighted children: (nL/n)GL + (nR/n)GR",
                "value": "(2/6 × 0.000) + (4/6 × 0.375) = 0.250"
              },
              {
                "id": "gini-gain",
                "label": "Gini gain = Parent Gini − weighted child Gini",
                "value": "0.250"
              }
            ]
          }
        ]
      }
    ]
  }
}
